//! Async Content-Length framing, ported from `crates/cli/src/commands/lsp.rs`'s
//! tested sync/server-role design to async/client-role. Same parsing rules, same
//! EOF-vs-malformed-header distinction; the size cap is checked before the receive
//! buffer is allocated, same as there.

use tokio::io::{AsyncBufRead, AsyncBufReadExt, AsyncReadExt, AsyncWrite, AsyncWriteExt};

use crate::error::{MalformedFrameReason, TscClientError};

/// Default cap on a single frame's declared `Content-Length`, matching
/// `crates/cli/src/commands/lsp.rs`'s `MAX_LSP_MESSAGE_BYTES`. `tsc`'s own frames are
/// server-controlled input with no upper bound of their own.
pub const DEFAULT_MAX_FRAME_BYTES: usize = 16 * 1024 * 1024; // 16 MiB

/// Reject an oversized frame before its receive buffer is allocated.
pub fn check_frame_len(len: usize, cap: usize) -> Result<(), TscClientError> {
    if len > cap {
        return Err(TscClientError::OversizedFrame { declared: len, cap });
    }
    Ok(())
}

enum HeaderReadResult {
    /// Stream ended before any header line was read — a normal, expected way for
    /// the child to close the connection.
    Eof,
    /// A header block was read (the loop reached the blank line) but contained no
    /// `Content-Length` line at all.
    NoHeaderLine,
    /// A `Content-Length` line was present but its value didn't parse as a number.
    UnparsableLength,
    Length(usize),
}

/// Reads header lines up to the blank-line terminator. A header block with no usable
/// `Content-Length` (missing or unparsable) leaves the body's byte length unknowable,
/// so the caller must not keep reading as if nothing happened — that desyncs every
/// subsequent frame, since the unconsumed body bytes get read as the next header block.
async fn read_content_length<R: AsyncBufRead + Unpin>(reader: &mut R) -> HeaderReadResult {
    let mut content_length: Option<usize> = None;
    let mut saw_header_line = false;
    let mut parse_failed = false;
    let mut line = String::new();

    loop {
        line.clear();
        // Any read error (including invalid UTF-8 in the header bytes) folds into
        // "0 bytes read", matching lsp.rs's `.unwrap_or(0)` — indistinguishable from
        // a clean disconnect, which is the safe default for a header we can't trust.
        if reader.read_line(&mut line).await.unwrap_or(0) == 0 {
            return HeaderReadResult::Eof;
        }
        if line == "\r\n" || line == "\n" {
            break;
        }
        if let Some(header) = line.strip_prefix("Content-Length: ") {
            saw_header_line = true;
            match header.trim().parse() {
                Ok(len) => content_length = Some(len),
                Err(_) => parse_failed = true,
            }
        }
    }

    match content_length {
        Some(len) => HeaderReadResult::Length(len),
        None if saw_header_line && parse_failed => HeaderReadResult::UnparsableLength,
        None => HeaderReadResult::NoHeaderLine,
    }
}

/// Reads one full Content-Length-framed message. `Ok(None)` is a clean EOF before any
/// header — the child closed its side. Every other outcome (malformed header, oversized
/// declaration, truncated body) is `Err` and the caller must treat the session as done;
/// none of them leave the stream at a recoverable position.
pub async fn read_frame<R: AsyncBufRead + Unpin>(
    reader: &mut R,
    cap: usize,
) -> Result<Option<Vec<u8>>, TscClientError> {
    let len = match read_content_length(reader).await {
        HeaderReadResult::Eof => return Ok(None),
        HeaderReadResult::NoHeaderLine => {
            return Err(TscClientError::MalformedFrame { reason: MalformedFrameReason::NoContentLengthHeader });
        }
        HeaderReadResult::UnparsableLength => {
            return Err(TscClientError::MalformedFrame { reason: MalformedFrameReason::UnparsableContentLength });
        }
        HeaderReadResult::Length(len) => len,
    };

    check_frame_len(len, cap)?;

    let mut buf = vec![0u8; len];
    reader
        .read_exact(&mut buf)
        .await
        .map_err(|_| TscClientError::MalformedFrame { reason: MalformedFrameReason::TruncatedBody })?;
    Ok(Some(buf))
}

pub async fn write_frame<W: AsyncWrite + Unpin>(writer: &mut W, body: &[u8]) -> std::io::Result<()> {
    let header = format!("Content-Length: {}\r\n\r\n", body.len());
    writer.write_all(header.as_bytes()).await?;
    writer.write_all(body).await?;
    writer.flush().await
}

#[cfg(test)]
mod tests {
    use super::*;

    fn reader_over(bytes: &[u8]) -> tokio::io::BufReader<&[u8]> {
        tokio::io::BufReader::new(bytes)
    }

    #[test]
    fn oversized_content_length_is_rejected() {
        let result = check_frame_len(DEFAULT_MAX_FRAME_BYTES + 1, DEFAULT_MAX_FRAME_BYTES);
        assert!(result.is_err(), "expected a Content-Length past the cap to be rejected, got {result:?}");
    }

    #[test]
    fn content_length_at_cap_is_accepted() {
        let result = check_frame_len(DEFAULT_MAX_FRAME_BYTES, DEFAULT_MAX_FRAME_BYTES);
        assert!(result.is_ok(), "expected a Content-Length exactly at the cap to be accepted, got {result:?}");
    }

    #[tokio::test]
    async fn true_stream_eof_is_distinct_from_a_malformed_header_block() {
        let mut reader = reader_over(b"");
        let result = read_frame(&mut reader, DEFAULT_MAX_FRAME_BYTES).await;
        assert!(matches!(result, Ok(None)), "expected clean EOF, got {result:?}");
    }

    #[tokio::test]
    async fn headerless_frame_is_reported_as_malformed_not_eof() {
        let mut reader = reader_over(b"X-Some-Other-Header: value\r\n\r\n");
        let result = read_frame(&mut reader, DEFAULT_MAX_FRAME_BYTES).await;
        assert!(
            matches!(
                result,
                Err(TscClientError::MalformedFrame { reason: MalformedFrameReason::NoContentLengthHeader })
            ),
            "expected NoContentLengthHeader, got {result:?}"
        );
    }

    #[tokio::test]
    async fn unparsable_content_length_is_reported_as_malformed() {
        let mut reader = reader_over(b"Content-Length: not-a-number\r\n\r\n");
        let result = read_frame(&mut reader, DEFAULT_MAX_FRAME_BYTES).await;
        assert!(
            matches!(
                result,
                Err(TscClientError::MalformedFrame { reason: MalformedFrameReason::UnparsableContentLength })
            ),
            "expected UnparsableContentLength, got {result:?}"
        );
    }

    #[tokio::test]
    async fn connection_closed_mid_header_before_blank_line_is_treated_as_eof() {
        let mut reader = reader_over(b"Content-Length: 10\r\n");
        let result = read_frame(&mut reader, DEFAULT_MAX_FRAME_BYTES).await;
        assert!(matches!(result, Ok(None)), "expected clean EOF, got {result:?}");
    }

    #[tokio::test]
    async fn non_utf8_header_bytes_are_treated_as_eof() {
        let mut reader = reader_over(b"Content-Length: 10\xFF\r\n\r\n");
        let result = read_frame(&mut reader, DEFAULT_MAX_FRAME_BYTES).await;
        assert!(matches!(result, Ok(None)), "expected clean EOF, got {result:?}");
    }

    #[tokio::test]
    async fn truncated_body_is_reported_as_malformed() {
        let mut reader = reader_over(b"Content-Length: 20\r\n\r\ntoo short");
        let result = read_frame(&mut reader, DEFAULT_MAX_FRAME_BYTES).await;
        assert!(
            matches!(result, Err(TscClientError::MalformedFrame { reason: MalformedFrameReason::TruncatedBody })),
            "expected TruncatedBody, got {result:?}"
        );
    }

    #[tokio::test]
    async fn a_well_formed_frame_round_trips() {
        let mut buf = Vec::new();
        write_frame(&mut buf, br#"{"id":1,"result":null}"#).await.unwrap();
        let mut reader = tokio::io::BufReader::new(&buf[..]);
        let frame = read_frame(&mut reader, DEFAULT_MAX_FRAME_BYTES).await.unwrap();
        assert_eq!(frame.as_deref(), Some(&br#"{"id":1,"result":null}"#[..]));
    }
}

