use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::Duration;

use dashmap::DashMap;
use tokio::io::BufReader;
use tokio::process::{ChildStdin, ChildStdout};
use tokio::sync::{mpsc, oneshot, Mutex as AsyncMutex};

use crate::error::{MalformedFrameReason, TscClientError};
use crate::protocol::{self, IncomingMessage, Notification, RequestId, RequestMessage};
use crate::transport;

/// A response's decoded `result`, tagged with the wire-arrival order it was read in —
/// see the module doc on [`Client::request`] for why that matters.
#[derive(Debug, Clone)]
pub struct TaggedResponse {
    pub value: serde_json::Value,
    pub seq: u64,
}

/// A session-ending failure. Kept separate from [`TscClientError`] (which can't
/// derive `Clone` — it wraps `io::Error`) so the single failure that ends a session
/// can be cheaply handed to every pending waiter.
#[derive(Debug, Clone, Copy)]
enum SessionEnd {
    Crashed(Option<std::process::ExitStatus>),
    Malformed(MalformedFrameReason),
    Oversized { declared: usize, cap: usize },
}

impl SessionEnd {
    fn into_error(self) -> TscClientError {
        match self {
            SessionEnd::Crashed(status) => TscClientError::Crashed { status },
            SessionEnd::Malformed(reason) => TscClientError::MalformedFrame { reason },
            SessionEnd::Oversized { declared, cap } => TscClientError::OversizedFrame { declared, cap },
        }
    }
}

struct ClientInner {
    stdin: AsyncMutex<ChildStdin>,
    pending: DashMap<u64, oneshot::Sender<Result<TaggedResponse, TscClientError>>>,
    next_id: AtomicU64,
    /// Wire-arrival order, stamped by the reader task as each frame is decoded — not
    /// issue order, not wall clock. Lets a caller mechanically check whether a query's
    /// answer could reflect an update it already saw acknowledged
    /// (`answer.seq > update_ack.seq`), the concrete slice of freshness tracking this
    /// crate can build without the real (still-churning) `updateSnapshot` wire shape.
    next_seq: AtomicU64,
    notifications: AsyncMutex<Option<mpsc::UnboundedReceiver<Notification>>>,
    max_frame_bytes: usize,
}

impl ClientInner {
    fn dispatch(&self, body: &[u8], seq: u64, notif_tx: &mpsc::UnboundedSender<Notification>) {
        match protocol::parse_incoming(body) {
            Ok(IncomingMessage::Response(response)) => {
                if let Some((_, tx)) = self.pending.remove(&response.id.0) {
                    let result = if let Some(error) = response.error {
                        Err(TscClientError::RpcError { code: error.code, message: error.message, data: error.data })
                    } else {
                        Ok(TaggedResponse { value: response.result.unwrap_or(serde_json::Value::Null), seq })
                    };
                    // A dropped receiver means the caller already gave up (e.g. timed
                    // out) — nothing left to deliver to.
                    let _ = tx.send(result);
                }
            }
            Ok(IncomingMessage::Notification(notification)) => {
                let _ = notif_tx.send(Notification { method: notification.method, params: notification.params });
            }
            Err(source) => {
                // A malformed *body* doesn't desync the stream — the declared
                // Content-Length was honored — so the session stays alive; this one
                // frame is just unusable.
                tracing::warn!("dropping unparsable tsc frame: {source}");
            }
        }
    }

    fn fail_all_pending(&self, end: SessionEnd) {
        let ids: Vec<u64> = self.pending.iter().map(|entry| *entry.key()).collect();
        for id in ids {
            if let Some((_, tx)) = self.pending.remove(&id) {
                let _ = tx.send(Err(end.into_error()));
            }
        }
    }
}

/// A handle to a running `tsc --api` session's JSON-RPC transport. Cheap to `Clone`
/// (an `Arc` underneath) so multiple concurrent callers can share one connection.
///
/// This is a raw request/response client, not a typed wrapper over TypeScript's
/// checker methods — implementing the actual algorithm
/// (`docs/type-checker-integration.md`, "The algorithm") is a separate, later pass;
/// this crate only has to prove the transport and process lifecycle are sound.
#[derive(Clone)]
pub struct Client(Arc<ClientInner>);

impl Client {
    /// Spawns the background reader task over `stdout`. Returns the `Client` handle
    /// plus that task's `JoinHandle`, so a caller (the supervisor) can detect a crash
    /// independently of any single in-flight `request()` call — the reader task exits
    /// with the [`TscClientError`] that ended the session.
    pub(crate) fn connect(
        stdin: ChildStdin,
        stdout: ChildStdout,
        max_frame_bytes: usize,
    ) -> (Self, tokio::task::JoinHandle<TscClientError>) {
        let (notif_tx, notif_rx) = mpsc::unbounded_channel();
        let inner = Arc::new(ClientInner {
            stdin: AsyncMutex::new(stdin),
            pending: DashMap::new(),
            next_id: AtomicU64::new(1),
            next_seq: AtomicU64::new(1),
            notifications: AsyncMutex::new(Some(notif_rx)),
            max_frame_bytes,
        });

        let reader_inner = Arc::clone(&inner);
        let handle = tokio::spawn(async move {
            let mut reader = BufReader::new(stdout);
            loop {
                match transport::read_frame(&mut reader, reader_inner.max_frame_bytes).await {
                    Ok(Some(body)) => {
                        let seq = reader_inner.next_seq.fetch_add(1, Ordering::SeqCst);
                        reader_inner.dispatch(&body, seq, &notif_tx);
                    }
                    Ok(None) => {
                        let end = SessionEnd::Crashed(None);
                        reader_inner.fail_all_pending(end);
                        return end.into_error();
                    }
                    Err(TscClientError::MalformedFrame { reason }) => {
                        let end = SessionEnd::Malformed(reason);
                        reader_inner.fail_all_pending(end);
                        return end.into_error();
                    }
                    Err(TscClientError::OversizedFrame { declared, cap }) => {
                        let end = SessionEnd::Oversized { declared, cap };
                        reader_inner.fail_all_pending(end);
                        return end.into_error();
                    }
                    Err(other) => {
                        // transport::read_frame's contract is: Ok(None) | Ok(Some) |
                        // Err(MalformedFrame) | Err(OversizedFrame). Anything else
                        // would be a bug in that contract, not a runtime failure.
                        unreachable!("read_frame returned an unexpected error variant: {other:?}")
                    }
                }
            }
        });

        (Client(inner), handle)
    }

    /// Ends the session for every pending and future caller with `Crashed { status }` —
    /// called by the supervisor once its own `child.wait()` resolves. Racing against
    /// the reader task's own EOF-triggered failure is fine: whichever fires first wins,
    /// the other finds `pending` already empty and is a no-op.
    pub(crate) fn report_crash(&self, status: Option<std::process::ExitStatus>) {
        self.0.fail_all_pending(SessionEnd::Crashed(status));
    }

    /// Sends a raw JSON-RPC request and awaits its response, or `Timeout` if `deadline`
    /// elapses first. A response that arrives after the deadline is a no-op send into
    /// a dropped receiver — it never gets attributed to a later, unrelated call.
    pub async fn request(
        &self,
        method: &str,
        params: serde_json::Value,
        deadline: Duration,
    ) -> Result<TaggedResponse, TscClientError> {
        let id = self.0.next_id.fetch_add(1, Ordering::SeqCst);
        let (tx, rx) = oneshot::channel();
        self.0.pending.insert(id, tx);

        let message = RequestMessage { id: RequestId(id), method: method.to_string(), params };
        let body = match serde_json::to_vec(&message) {
            Ok(body) => body,
            Err(source) => {
                self.0.pending.remove(&id);
                return Err(TscClientError::Serialize(source));
            }
        };

        {
            let mut stdin = self.0.stdin.lock().await;
            if let Err(source) = transport::write_frame(&mut *stdin, &body).await {
                self.0.pending.remove(&id);
                return Err(TscClientError::Write(source));
            }
        }

        match tokio::time::timeout(deadline, rx).await {
            Ok(Ok(result)) => result,
            Ok(Err(_sender_dropped)) => Err(TscClientError::SessionClosed),
            Err(_elapsed) => {
                self.0.pending.remove(&id);
                Err(TscClientError::Timeout { method: method.to_string(), after: deadline })
            }
        }
    }

    /// Single-consumer: returns `Some` exactly once, `None` on every later call. Keeps
    /// `Client` itself cheaply `Clone` without also fanning notifications out to every
    /// clone.
    pub fn take_notifications(&self) -> Option<mpsc::UnboundedReceiver<Notification>> {
        self.0.notifications.try_lock().ok()?.take()
    }
}

use std::process::Stdio;
use std::time::{Duration, Instant};

use camino::{Utf8Path, Utf8PathBuf};
use tokio::io::AsyncBufReadExt;
use tokio::process::{Child, Command};

use crate::client::{Client, TaggedResponse};
use crate::error::TscClientError;

const DEFAULT_HANDSHAKE_TIMEOUT: Duration = Duration::from_secs(10); // measured 33-72ms; generous headroom
const SHUTDOWN_GRACE: Duration = Duration::from_secs(2);
const MAX_RESTARTS: u32 = 3;
const RESTART_WINDOW: Duration = Duration::from_secs(60);
const BACKOFF_STEPS: [Duration; 3] = [Duration::from_millis(200), Duration::from_millis(400), Duration::from_millis(800)];
const BACKOFF_MAX: Duration = Duration::from_secs(5);

#[derive(Debug, Clone)]
pub struct SupervisorConfig {
    /// Path to the `tsc` binary, e.g. `node_modules/typescript/bin/tsc` — resolving
    /// that path is the caller's job, not this crate's.
    pub tsc_path: Utf8PathBuf,
    /// Passed as `tsc --api --async --cwd <cwd>`.
    pub cwd: Utf8PathBuf,
    /// `tsc_path`'s adjacent `package.json` "version" must be one of these, checked
    /// before every spawn. The protocol has no version handshake (ADR 0006), so this
    /// is the whole mechanism — the caller decides which exact build(s) are pinned.
    pub expected_versions: &'static [&'static str],
    pub handshake_timeout: Duration,
    pub max_frame_bytes: usize,
}

impl SupervisorConfig {
    pub fn new(tsc_path: Utf8PathBuf, cwd: Utf8PathBuf, expected_versions: &'static [&'static str]) -> Self {
        Self {
            tsc_path,
            cwd,
            expected_versions,
            handshake_timeout: DEFAULT_HANDSHAKE_TIMEOUT,
            max_frame_bytes: crate::transport::DEFAULT_MAX_FRAME_BYTES,
        }
    }
}

fn check_version(tsc_path: &Utf8Path, expected: &'static [&'static str]) -> Result<(), TscClientError> {
    let reason_at = |reason: String| TscClientError::VersionCheckFailed { path: tsc_path.to_owned(), reason };

    let Some(package_json) = tsc_path.parent().and_then(|bin_dir| bin_dir.parent()).map(|pkg_dir| pkg_dir.join("package.json"))
    else {
        return Err(reason_at("tsc_path has no grandparent directory to find package.json in".to_string()));
    };

    let contents = std::fs::read_to_string(&package_json).map_err(|source| reason_at(format!("reading {package_json}: {source}")))?;
    let value: serde_json::Value =
        serde_json::from_str(&contents).map_err(|source| reason_at(format!("parsing {package_json}: {source}")))?;
    let Some(found) = value.get("version").and_then(|v| v.as_str()) else {
        return Err(reason_at(format!("{package_json} has no \"version\" string")));
    };

    if expected.contains(&found) {
        Ok(())
    } else {
        Err(TscClientError::UnsupportedVersion { path: tsc_path.to_owned(), found: found.to_string(), expected })
    }
}

fn spawn_stderr_drain(stderr: tokio::process::ChildStderr) {
    // Must be continuously drained: an unread stderr pipe fills its OS buffer and can
    // deadlock the child. Logged at debug, not warn — tsc's own diagnostic chatter
    // isn't inherently an error, but it's valuable when a crash needs explaining.
    tokio::spawn(async move {
        let mut lines = tokio::io::BufReader::new(stderr).lines();
        while let Ok(Some(line)) = lines.next_line().await {
            tracing::debug!(target: "tsc_client::stderr", "{line}");
        }
    });
}

/// Spawns one `tsc --api` process and wires up its transport. Split out from
/// `Supervisor::spawn`/`restart` so a restart can replace the process/client/reader
/// triple without losing the restart-attempt bookkeeping a fresh `Supervisor` would
/// otherwise reset.
async fn spawn_process(
    config: &SupervisorConfig,
) -> Result<(Child, Client, tokio::task::JoinHandle<TscClientError>), TscClientError> {
    check_version(&config.tsc_path, config.expected_versions)?;

    let mut command = Command::new(config.tsc_path.as_std_path());
    command.arg("--api").arg("--async").arg("--cwd").arg(config.cwd.as_std_path());
    command.stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped());
    // Best-effort fallback if `Supervisor::shutdown` is never called — this alone
    // doesn't guarantee reaping (Drop can't await), only `.shutdown()` does.
    command.kill_on_drop(true);

    let mut child =
        command.spawn().map_err(|source| TscClientError::SpawnFailed { path: config.tsc_path.clone(), source })?;

    let Some(stdin) = child.stdin.take() else { unreachable!("stdin is None despite Stdio::piped()") };
    let Some(stdout) = child.stdout.take() else { unreachable!("stdout is None despite Stdio::piped()") };
    let Some(stderr) = child.stderr.take() else { unreachable!("stderr is None despite Stdio::piped()") };

    spawn_stderr_drain(stderr);
    let (client, reader_handle) = Client::connect(stdin, stdout, config.max_frame_bytes);

    Ok((child, client, reader_handle))
}

/// Owns one `tsc --api` child process across its lifetime: spawn, version check,
/// crash-triggered restart (bounded, to avoid a restart storm), and shutdown/reaping.
pub struct Supervisor {
    child: Child,
    client: Client,
    reader_handle: tokio::task::JoinHandle<TscClientError>,
    config: SupervisorConfig,
    restart_attempts: Vec<Instant>,
    /// Set once a restart-storm cap is hit. Terminal — every later call short-circuits
    /// without touching the process again.
    failed: bool,
}

impl Supervisor {
    pub async fn spawn(config: SupervisorConfig) -> Result<Self, TscClientError> {
        let (child, client, reader_handle) = spawn_process(&config).await?;
        Ok(Self { child, client, reader_handle, config, restart_attempts: Vec::new(), failed: false })
    }

    /// The current session's low-level handle. Cheap to clone. After a
    /// supervisor-driven restart, `Client` clones obtained *before* the restart are
    /// permanently `SessionClosed` — call this again to get the live one.
    pub fn client(&self) -> Client {
        self.client.clone()
    }

    /// True while the current process's reader task is still running and the
    /// supervisor hasn't permanently failed. A crash between calls to this method and
    /// the next `request()` is still possible — this is a snapshot, not a guarantee.
    pub fn is_alive(&self) -> bool {
        !self.reader_handle.is_finished() && !self.failed
    }

    /// Sends a request through the current session. On `Crashed`, restarts once (if
    /// the restart budget allows) and retries the same call once before giving up —
    /// a request lost to a crash is never silently replayed more than that.
    pub async fn request(
        &mut self,
        method: &str,
        params: serde_json::Value,
        deadline: Duration,
    ) -> Result<TaggedResponse, TscClientError> {
        if self.failed {
            return Err(TscClientError::RestartStormDetected {
                attempts: self.restart_attempts.len() as u32,
                window: RESTART_WINDOW,
            });
        }

        match self.client.request(method, params.clone(), deadline).await {
            Err(TscClientError::Crashed { .. }) => {
                self.restart().await?;
                self.client.request(method, params, deadline).await
            }
            other => other,
        }
    }

    async fn restart(&mut self) -> Result<(), TscClientError> {
        let now = Instant::now();
        self.restart_attempts.retain(|attempt| now.duration_since(*attempt) < RESTART_WINDOW);

        if self.restart_attempts.len() as u32 >= MAX_RESTARTS {
            self.failed = true;
            return Err(TscClientError::RestartStormDetected {
                attempts: self.restart_attempts.len() as u32,
                window: RESTART_WINDOW,
            });
        }

        let backoff = BACKOFF_STEPS.get(self.restart_attempts.len()).copied().unwrap_or(BACKOFF_MAX);
        self.restart_attempts.push(now);
        tokio::time::sleep(backoff).await;

        // Best-effort cleanup of the crashed process before respawning — it may
        // already be gone, so failures here are expected and ignored.
        let _ = self.child.start_kill();
        let _ = self.child.wait().await;

        let (child, client, reader_handle) = spawn_process(&self.config).await?;
        self.child = child;
        self.client = client;
        self.reader_handle = reader_handle;
        Ok(())
    }

    /// Ends the session and guarantees the child is reaped, never left as a zombie:
    /// stop reading, race a grace period against a clean exit, force-kill past it,
    /// then unconditionally wait so the OS process table entry is always cleared.
    pub async fn shutdown(mut self) -> Result<(), TscClientError> {
        self.reader_handle.abort();
        drop(self.client);

        match tokio::time::timeout(SHUTDOWN_GRACE, self.child.wait()).await {
            Ok(Ok(_status)) => Ok(()),
            Ok(Err(source)) => Err(TscClientError::Reap(source)),
            Err(_elapsed) => {
                let _ = self.child.start_kill();
                let _ = self.child.wait().await; // unconditional — never left unreaped
                Ok(())
            }
        }
    }
}

