1	//! A scenario-driven fake `tsc --api` process for the Lifecycle-gate test suite.
2	//! Scenario is picked via the `FAKE_TSC_SCENARIO` env var (env, not argv, matching
3	//! `crates/cli/src/config.rs`'s precedent for test/caller-controlled input):
4	//! `echo` (default), `never_respond`, `hang_after_n:<N>`, `exit_after:<N>:<code>`,
5	//! `crash_immediately:<code>`, `garbage_bytes`, `bad_content_length`,
6	//! `oversized_frame:<N>`, `truncated_body`, `reorder_ack`, `shutdown_slow:<ms>`.
7	//!
8	//! Valid-frame scenarios are built on this crate's own `transport::{read_frame,
9	//! write_frame}`, so this fixture can't drift from what the real client parses;
10	//! bad-frame scenarios intentionally hand-write raw bytes instead.
11	
12	use std::time::Duration;
13	
14	use oxc_react_docgen_tsc_client::transport::{read_frame, write_frame, DEFAULT_MAX_FRAME_BYTES};
15	use tokio::io::{AsyncWriteExt, BufReader};
16	
17	#[tokio::main]
18	async fn main() {
19	    let scenario = std::env::var("FAKE_TSC_SCENARIO").unwrap_or_else(|_| "echo".to_string());
20	    let mut parts = scenario.splitn(3, ':');
21	    let name = parts.next().unwrap_or("echo");
22	    let arg1 = parts.next();
23	    let arg2 = parts.next();
24	
25	    match name {
26	        "never_respond" => never_respond().await,
27	        "hang_after_n" => hang_after_n(arg1.and_then(|s| s.parse().ok()).unwrap_or(0)).await,
28	        "exit_after" => {
29	            exit_after(arg1.and_then(|s| s.parse().ok()).unwrap_or(0), arg2.and_then(|s| s.parse().ok()).unwrap_or(1))
30	                .await;
31	        }
32	        "crash_immediately" => std::process::exit(arg1.and_then(|s| s.parse().ok()).unwrap_or(1)),
33	        "garbage_bytes" => garbage_bytes().await,
34	        "bad_content_length" => bad_content_length().await,
35	        "oversized_frame" => oversized_frame(arg1.and_then(|s| s.parse().ok()).unwrap_or(usize::MAX)).await,
36	        "truncated_body" => truncated_body().await,
37	        "reorder_ack" => reorder_ack().await,
38	        "shutdown_slow" => shutdown_slow(arg1.and_then(|s| s.parse().ok()).unwrap_or(10_000)).await,
39	        _ => echo().await,
40	    }
41	}
42	
43	fn request_id(request: &serde_json::Value) -> serde_json::Value {
44	    request.get("id").cloned().unwrap_or(serde_json::Value::Null)
45	}
46	
47	async fn read_request<R: tokio::io::AsyncBufRead + Unpin>(reader: &mut R) -> Option<serde_json::Value> {
48	    match read_frame(reader, DEFAULT_MAX_FRAME_BYTES).await {
49	        Ok(Some(body)) => serde_json::from_slice(&body).ok(),
50	        _ => None,
51	    }
52	}
53	
54	async fn respond<W: tokio::io::AsyncWrite + Unpin>(writer: &mut W, id: &serde_json::Value, result: serde_json::Value) {
55	    let body = serde_json::json!({ "id": id, "result": result });
56	    if let Ok(bytes) = serde_json::to_vec(&body) {
57	        let _ = write_frame(writer, &bytes).await;
58	    }
59	}
60	
61	async fn respond_error<W: tokio::io::AsyncWrite + Unpin>(
62	    writer: &mut W,
63	    id: &serde_json::Value,
64	    code: i64,
65	    message: &str,
66	) {
67	    let body = serde_json::json!({ "id": id, "error": { "code": code, "message": message } });
68	    if let Ok(bytes) = serde_json::to_vec(&body) {
69	        let _ = write_frame(writer, &bytes).await;
70	    }
71	}
72	
73	/// Baseline: echoes `params` back as `result.echo`, or replies with an `error` object
74	/// when `params.fail` is `true` — used to test that one failing call doesn't affect a
75	/// concurrently in-flight sibling (partial project failure).
76	async fn echo() {
77	    let mut reader = BufReader::new(tokio::io::stdin());
78	    let mut stdout = tokio::io::stdout();
79	    while let Some(request) = read_request(&mut reader).await {
80	        let id = request_id(&request);
81	        let params = request.get("params").cloned().unwrap_or(serde_json::Value::Null);
82	        if params.get("fail").and_then(serde_json::Value::as_bool).unwrap_or(false) {
83	            respond_error(&mut stdout, &id, -32000, "requested failure").await;
84	        } else {
85	            respond(&mut stdout, &id, serde_json::json!({ "echo": params })).await;
86	        }
87	    }
88	}
89	
90	/// Reads and discards requests forever, never responding — exercises the client's
91	/// per-request timeout.
92	async fn never_respond() {
93	    let mut reader = BufReader::new(tokio::io::stdin());
94	    while read_request(&mut reader).await.is_some() {}
95	}
96	
97	/// Responds normally to the first `n` requests, then keeps reading (so the pipe never
98	/// backs up) without ever responding again.
99	async fn hang_after_n(n: usize) {
100	    let mut reader = BufReader::new(tokio::io::stdin());
101	    let mut stdout = tokio::io::stdout();
102	    let mut count = 0usize;
103	    while let Some(request) = read_request(&mut reader).await {
104	        count += 1;
105	        if count > n {
106	            continue;
107	        }
108	        respond(&mut stdout, &request_id(&request), serde_json::json!({ "ok": true })).await;
109	    }
110	}
111	
112	/// Responds normally to the first `n` requests, then exits with `code` — exercises
113	/// crash detection mid-session (a request issued after the `n`th gets no response).
114	async fn exit_after(n: usize, code: i32) {
115	    let mut reader = BufReader::new(tokio::io::stdin());
116	    let mut stdout = tokio::io::stdout();
117	    let mut count = 0usize;
118	    while let Some(request) = read_request(&mut reader).await {
119	        count += 1;
120	        respond(&mut stdout, &request_id(&request), serde_json::json!({ "ok": true })).await;
121	        if count >= n {
122	            std::process::exit(code);
123	        }
124	    }
125	}
126	
127	async fn garbage_bytes() {
128	    // Ends with the blank-line header terminator so the reader reaches "a header block
129	    // was read, but it has no Content-Length" rather than hitting EOF mid-header.
130	    let mut stdout = tokio::io::stdout();
131	    let _ = stdout.write_all(b"this is not a Content-Length frame at all\r\n\r\n").await;
132	    let _ = stdout.flush().await;
133	    tokio::time::sleep(Duration::from_millis(300)).await;
134	}
135	
136	async fn bad_content_length() {
137	    let mut stdout = tokio::io::stdout();
138	    let _ = stdout.write_all(b"Content-Length: not-a-number\r\n\r\n").await;
139	    let _ = stdout.flush().await;
140	    tokio::time::sleep(Duration::from_millis(300)).await;
141	}
142	
143	/// Declares a `Content-Length` far larger than the client's cap and never writes that
144	/// many bytes — the client must reject based on the declared length alone.
145	async fn oversized_frame(declared: usize) {
146	    let mut stdout = tokio::io::stdout();
147	    let header = format!("Content-Length: {declared}\r\n\r\n");
148	    let _ = stdout.write_all(header.as_bytes()).await;
149	    let _ = stdout.flush().await;
150	    tokio::time::sleep(Duration::from_millis(300)).await;
151	}
152	
153	async fn truncated_body() {
154	    let mut stdout = tokio::io::stdout();
155	    let _ = stdout.write_all(b"Content-Length: 100\r\n\r\ntoo short").await;
156	    let _ = stdout.flush().await;
157	    tokio::time::sleep(Duration::from_millis(300)).await;
158	}
159	
160	/// Reads two requests, answers the second one first — proves a response's `seq`
161	/// reflects wire-arrival order, not issue order (the stale-notification mechanism).
162	async fn reorder_ack() {
163	    let mut reader = BufReader::new(tokio::io::stdin());
164	    let mut stdout = tokio::io::stdout();
165	    let Some(first) = read_request(&mut reader).await else { return };
166	    let Some(second) = read_request(&mut reader).await else { return };
167	    respond(&mut stdout, &request_id(&second), serde_json::json!({ "order": "second" })).await;
168	    respond(&mut stdout, &request_id(&first), serde_json::json!({ "order": "first" })).await;
169	    while let Some(request) = read_request(&mut reader).await {
170	        respond(&mut stdout, &request_id(&request), serde_json::json!({ "ok": true })).await;
171	    }
172	}
173	
174	/// Answers requests normally but ignores shutdown for `delay_ms` before exiting —
175	/// forces the supervisor's shutdown grace period to elapse into a force-kill.
176	async fn shutdown_slow(delay_ms: u64) {
177	    let mut reader = BufReader::new(tokio::io::stdin());
178	    let mut stdout = tokio::io::stdout();
179	    let deadline = tokio::time::Instant::now() + Duration::from_millis(delay_ms);
180	    loop {
181	        let remaining = deadline.saturating_duration_since(tokio::time::Instant::now());
182	        if remaining.is_zero() {
183	            break;
184	        }
185	        tokio::select! {
186	            request = read_request(&mut reader) => {
187	                let Some(request) = request else { break };
188	                respond(&mut stdout, &request_id(&request), serde_json::json!({ "ok": true })).await;
189	            }
190	            () = tokio::time::sleep(remaining) => break,
191	        }
192	    }
193	}
